import { readFile, writeFile } from 'node:fs/promises';

const contentPath = new URL(
  './content/character-guides-1.4.json',
  import.meta.url,
);
const migrationPath = new URL(
  '../migrations/0051_complete_character_guides.sql',
  import.meta.url,
);
const { patch, guides, teams } = JSON.parse(
  await readFile(contentPath, 'utf8'),
);
const sqlString = (value) => `'${String(value).replaceAll("'", "''")}'`;
const values = (...fields) => fields.map(sqlString).join(', ');
const statements = [
  '-- Generated by scripts/generate-character-guides.mjs.',
  '-- Resolve character IDs by slug and only seed a guide if it has no published guide.',
  'CREATE TABLE new_character_guides_0051 (id TEXT PRIMARY KEY, character_id TEXT NOT NULL);',
];

for (const guide of guides) {
  const id = `guide-${guide.character}-0051`;
  const slug = `${guide.character}-build-guide`;
  const guard = `EXISTS (SELECT 1 FROM new_character_guides_0051 WHERE id = ${sqlString(id)})`;
  statements.push(
    `INSERT INTO new_character_guides_0051 (id, character_id)
SELECT ${sqlString(id)}, c.id FROM characters c
WHERE c.slug = ${sqlString(guide.character)} AND c.status = 'published'
  AND NOT EXISTS (SELECT 1 FROM guides g WHERE g.id = ${sqlString(id)}
    OR g.slug = ${sqlString(slug)}
    OR (g.character_id = c.id AND g.status = 'published'));`,
    `INSERT INTO guides (id, slug, character_id, title, summary, status, patch_version)
SELECT id, ${sqlString(slug)}, character_id, ${values(guide.title, guide.summary, 'published', patch)}
FROM new_character_guides_0051 WHERE id = ${sqlString(id)};`,
  );

  for (const [index, section] of guide.sections.entries()) {
    const meta = section.visual ? { visual: section.visual } : {};
    statements.push(
      `INSERT INTO guide_sections (id, guide_id, title, section_type, content_markdown, position, meta_json)
SELECT ${values(`${id}-${section.type}`, id, section.title, section.type, section.content ?? '')},
  ${index + 1}, ${sqlString(JSON.stringify(meta))}
WHERE ${guard};`,
    );
  }

  for (const [index, teamKey] of guide.teams.entries()) {
    const team = teams[teamKey];
    const teamId = `team-${guide.character}-0051-${index + 1}`;
    const memberSlugs = team.members.map(([slug]) => slug);
    statements.push(
      `INSERT OR IGNORE INTO teams (id, slug, guide_id, title, team_type, budget, difficulty,
  good_at, weak_at, synergy, rotation, rotation_steps_json, status)
SELECT ${values(teamId, teamId, id, team.title, team.type, team.budget, team.difficulty)},
  ${values(team.good, team.weak, team.synergy, team.steps.join('\n'), JSON.stringify(team.steps), 'published')}
WHERE ${guard}
  AND (SELECT COUNT(*) FROM characters WHERE slug IN (${values(...memberSlugs)}) AND status = 'published') = ${memberSlugs.length};`,
    );
    for (const [position, [memberSlug, role]] of team.members.entries()) {
      statements.push(
        `INSERT OR IGNORE INTO team_members (team_id, character_id, role, position)
SELECT ${sqlString(teamId)}, c.id, ${sqlString(role)}, ${position}
FROM characters c WHERE c.slug = ${sqlString(memberSlug)}
  AND EXISTS (SELECT 1 FROM teams WHERE id = ${sqlString(teamId)} AND guide_id = ${sqlString(id)})
  AND ${guard};`,
      );
    }
  }
}

statements.push(
  `-- Replace the original announcement placeholder using the released kit.
UPDATE characters
SET attribute = 'Лакшана', role = 'Основной ДД', type = 'Основной ДД',
    short_description = 'Урон Лакшаны по целям под Розыском и Реморой.',
    summary = 'Накапливает Преступление и расходует его на усиленный Окончательный приговор.',
    tags_json = '["Лакшана","Основной ДД","Ремора"]',
    updated_at = CURRENT_TIMESTAMP
WHERE slug = 'chaos' AND attribute = 'Хаос' AND role = 'Требует проверки'
  AND short_description = 'Анонсированный персонаж. Мета-позиция будет обновлена после тестов.'
  AND summary = 'Карточка оставлена как заготовка для будущего гайда.'
  AND json(tags_json) = '["анонс","нужны тесты","не подтверждено"]'
  AND EXISTS (SELECT 1 FROM new_character_guides_0051 WHERE character_id = characters.id);`,
  `UPDATE character_profiles
SET arc_type = CASE
  WHEN character_id = (SELECT id FROM characters WHERE slug = 'chaos') THEN 'Гибридный'
  ELSE 'Твёрдый' END
WHERE COALESCE(arc_type, '') = ''
  AND character_id IN (SELECT id FROM characters WHERE slug IN ('chaos', 'esper-zero'))
  AND EXISTS (SELECT 1 FROM new_character_guides_0051 WHERE character_id = character_profiles.character_id);`,
  'DROP TABLE new_character_guides_0051;',
);
const migration = statements.join('\n\n') + '\n';

if (process.argv.includes('--check')) {
  const saved = await readFile(migrationPath, 'utf8');
  if (saved.replaceAll('\r\n', '\n') !== migration) {
    throw new Error(
      'Миграция не совпадает с данными гайдов. Запустите генератор.',
    );
  }
} else {
  await writeFile(migrationPath, migration);
}
